<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,Arial,sans-serif;font-size:11px;line-height:1.45;color:#111}h1{font-size:21px;margin:0 0 2px}h2{font-size:12px;text-transform:uppercase;letter-spacing:.5px;border-bottom:1px solid #222;margin:15px 0 6px;padding-bottom:2px}p{margin:3px 0}.contact{font-size:10px;color:#333}.entry{margin-bottom:9px}.meta{font-size:10px;color:#333}ul{margin:3px 0 0 16px;padding:0}li{margin-bottom:2px}</style></head><body><h1>{{$resume->full_name}}</h1>@if($resume->headline)<p><strong>{{$resume->headline}}</strong></p>@endif<p class="contact">{{collect([$resume->email,$resume->phone,$resume->location])->filter()->implode(' | ')}}</p>@if($resume->summary)<h2>Summary</h2><p>{{$resume->summary}}</p>@endif @if($resume->skills)<h2>Skills</h2><p>{{implode(', ',$resume->skills)}}</p>@endif @if($resume->experience)<h2>Experience</h2>@foreach($resume->experience as $item)<div class="entry"><p><strong>{{$item['role']??''}}{{filled($item['company']??null)?' — '.$item['company']:''}}</strong></p><p class="meta">{{collect([$item['location']??null,collect([$item['start_date']??null,$item['end_date']??null])->filter()->implode(' - ')])->filter()->implode(' | ')}}</p>@if($item['bullets']??[])<ul>@foreach($item['bullets'] as $bullet)<li>{{$bullet}}</li>@endforeach</ul>@endif</div>@endforeach @endif @if($resume->education)<h2>Education</h2>@foreach($resume->education as $item)<div class="entry"><p><strong>{{$item['degree']??''}}{{filled($item['institution']??null)?' — '.$item['institution']:''}}</strong></p><p class="meta">{{collect([$item['location']??null,$item['end_date']??null,$item['gpa']??null])->filter()->implode(' | ')}}</p></div>@endforeach @endif @if($resume->links)<h2>Links</h2>@foreach($resume->links as $item)<p>{{$item['label']??''}}: {{$item['url']??''}}</p>@endforeach @endif</body></html>
